mapper.sql:
from forum_post fp
join users u on fp.user_id=u.id



            and fp.status = #{dto.status}



            and fp.user_id = #{id} and fp.status = #{dto.status}


            and (fp.status=1 or(fp.user_id=#{id} and fp.status in (0,2)))



        and(fp.title like concat('%',#{dto.keyword},'%') or fp.content like concat('%',#{dto.keyword},'%'))


        and(fp.tag=#{dto.tag})


        and fp.user_id=#{id}


        AND fp.is_essence = 1

mapper.select:
SELECT FROM forum_comment fc JOIN users u ON u.id = fc.user_id LEFT JOIN users u2 ON u2.id = fc.reply_to_user_id WHERE fc.parent_id IN
#{pid}
AND fc.status = 1 ORDER BY fc.create_time ASC, fc.id ASC

mapper.update:
UPDATE forum_post
is_top = #{dto.isTop}, is_essence = #{dto.isEssence}, is_locked = #{dto.isLocked}, status = #{dto.status},
WHERE id = #{id}

UPDATE forum_report
SET status = #{status}, handle_by = #{handleBy}, handle_time = NOW(),
    handle_action = #{handleAction}, handle_remark = #{handleRemark}
WHERE id = #{id}

UPDATE users SET status = 0,
mute_until = CASE WHEN #{days} IS NULL OR #{days} = 0 THEN NULL
ELSE DATE_ADD(NOW(), INTERVAL #{days} DAY) END,
mute_reason = #{reason}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM announcement a
LEFT JOIN announcement_read r ON r.announcement_id = a.id AND r.user_id = #{me}
WHERE a.status = 1 AND r.id IS NULL

mapper.update:
UPDATE announcement
title = #{dto.title}, content = #{dto.content}, type = #{dto.type}, is_top = #{dto.isTop}, status = #{dto.status},
WHERE id = #{id}
